?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Authority Submission Kit | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f7f9fc;color:#172033}.wrap{max-width:1180px;margin:30px auto;padding:0 20px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}.copy{white-space:pre-wrap;background:#f8fafc;border:1px solid #e2e8f0;border-radius:9px;padding:11px}.muted{color:#64748b;font-size:13px}.badge{display:inline-block;padding:3px 8px;border-radius:999px;background:#eef2ff;font-size:11px}button{border:0;background:#1d4ed8;color:#fff;border-radius:8px;padding:8px 11px;cursor:pointer}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}a{color:#1d4ed8}</style></head><body><main class="wrap"><p><a href="/authority-admin">← Authority execution queue</a></p><h1>Authority Submission Kit</h1><p class="muted">Controlled copy for external profiles and editorial outreach. Nothing on this page means a profile, submission, publication, endorsement or backlink already exists.</p><section class="card"><h2>Canonical positioning</h2><p><strong><?=h($b['tagline'])?></strong></p><div class="copy" id="short"><?=h($b['short'])?></div><p><button onclick="copyId('short')">Copy short</button></p><div class="copy" id="medium"><?=h($b['medium'])?></div><p><button onclick="copyId('medium')">Copy medium</button></p><div class="copy" id="long"><?=h($b['long'])?></div><p><button onclick="copyId('long')">Copy long</button></p><h3>Ownership / independence</h3><div class="copy" id="ownership"><?=h($b['ownership'])?></div><p><button onclick="copyId('ownership')">Copy disclosure</button></p><h3>Boundaries</h3><div class="copy"><?=h($b['boundaries'])?></div></section><div class="grid"><?php foreach($channels as $key=>$c):?><section class="card"><div class="row"><h2 style="margin:0"><?=h($c['name'])?></h2><span class="badge"><?=h($c['status'])?></span></div><h3>Headline</h3><div class="copy" id="<?=h($key)?>-headline"><?=h($c['headline'])?></div><p><button onclick="copyId('<?=h($key)?>-headline')">Copy headline</button></p><h3>Description / pitch</h3><div class="copy" id="<?=h($key)?>-desc"><?=h($c['description'])?></div><p><button onclick="copyId('<?=h($key)?>-desc')">Copy description</button></p><h3>Tagged link</h3><div class="copy" id="<?=h($key)?>-link"><?=h($c['link'])?></div><p><button onclick="copyId('<?=h($key)?>-link')">Copy link</button></p><p class="muted"><?=h($c['notes'])?></p></section><?php endforeach;?></div><section class="card"><h2>Canonical assets</h2><p><a href="<?=h($b['about'])?>" target="_blank" rel="noopener">About / citation resource</a> · <a href="<?=h($b['methodology'])?>" target="_blank" rel="noopener">Methodology</a> · <a href="<?=h($b['trust'])?>" target="_blank" rel="noopener">Trust & independence</a> · <a href="<?=h($b['logo'])?>" target="_blank" rel="noopener">Official logo</a></p></section></main><script>async function copyId(id){let el=document.getElementById(id);if(!el)return;try{await navigator.clipboard.writeText(el.innerText)}catch(e){let r=document.createRange();r.selectNodeContents(el);let s=getSelection();s.removeAllRanges();s.addRange(r);document.execCommand('copy');s.removeAllRanges()}}</script></body></html>
